/**
 * Task domain model.
 *
 * A Task is the unit of work in the orchestrator.
 * It moves through a state machine: todo → in_progress → review → done.
 */

export type TaskStatus =
  | 'todo'
  | 'in_progress'
  | 'retrying'
  | 'review'
  /** Waiting for a human decision (see Decision); not dispatched meanwhile. */
  | 'waiting_decision'
  | 'done'
  | 'failed'
  | 'cancelled';

/** Label applied to tasks auto-generated by the orchestrator for autonomous agents. */
export const AUTONOMOUS_LABEL = 'autonomous' as const;

export type WorkspaceMode = 'shared' | 'worktree' | 'isolated';

export type ReviewCriterion = 'test_pass' | 'typecheck' | 'lint';

export interface ReviewResult {
  criterion: ReviewCriterion;
  passed: boolean;
  output: string;
}

export interface TaskProof {
  branch?: string;
  pr_url?: string;
  files_changed: string[];
  test_results?: string;
  agent_summary?: string;
  /** Worktree branch has been merged into the main branch (set on approval). */
  merged?: boolean;
  /** Commit of the main branch last merged into the task branch (before review). */
  synced_main?: string;
  /** Files that conflicted when syncing main; checked for leftover markers before committing. */
  conflict_files?: string[];
}

export interface Task {
  id: string;
  title: string;
  description: string;
  status: TaskStatus;
  priority: number;
  /** Role that should do this task — any idle instance of it may take it. */
  role?: string;
  assignee?: string;
  labels: string[];
  depends_on: string[];
  created_at: string;
  updated_at: string;
  attempts: number;
  max_attempts: number;
  workspace_mode?: WorkspaceMode;
  workspace?: string;
  proof?: TaskProof;
  review_criteria?: ReviewCriterion[];
  review_results?: ReviewResult[];
  scope?: string[];
  feedback?: string;
  /** Approved for merging: ORCH syncs main, re-verifies if main moved, then merges. */
  approved?: boolean;
  /** Times ORCH sent the task back to its agent (main merge conflict, or review failing after sync). */
  send_backs?: number;
  goalId?: string;
  attachments?: string[];
  /** Planning task of this plan (the planner submits the plan; it never merges code). */
  plan_id?: string;
  /** Files this task must produce (paths or globs, relative to the project root). */
  produces?: string[];
  /** Contract files this task must follow and must not change (paths). */
  uses?: string[];
  /** PRD this task implements (its latest version goes into the prompt). */
  prd?: string;
  /** Drafting task of this PRD (the PM submits it; it never merges code). */
  prd_draft?: string;
  /** PM task answering this decision (it answers or escalates; it never merges code). */
  triage_decision_id?: string;
  /**
   * A human cancelled it: ORCH removes its worktree and branch. (Tasks cancelled
   * by ORCH itself, e.g. after a restart, keep theirs so no work is lost.)
   */
  discard_work?: boolean;
  /** Review task: the task it reviews (the reviewer submits findings; it never merges code). */
  review_of?: string;
  /** Review of this task by a reviewer role (rounds, findings). */
  review?: import('./review.js').TaskReview;
}

export interface CreateTaskInput {
  title: string;
  description?: string;
  priority?: number;
  role?: string;
  assignee?: string;
  labels?: string[];
  depends_on?: string[];
  max_attempts?: number;
  workspace_mode?: WorkspaceMode;
  review_criteria?: ReviewCriterion[];
  scope?: string[];
  goalId?: string;
  attachments?: string[];
  /** Create the task in waiting_decision: a human approves before it starts. */
  needs_decision?: boolean;
  /** Makes it the planning task of this plan. */
  plan_id?: string;
  produces?: string[];
  uses?: string[];
  prd?: string;
  prd_draft?: string;
  triage_decision_id?: string;
  review_of?: string;
}
